"use client";

import { useEffect, useState } from "react";
import { CommandMenu } from "@/components/command-menu";
import { getResumeData } from "@/data/resume-data";
import { generateResumeStructuredData } from "@/lib/structured-data";
import { useLanguage } from "@/lib/language-context";
import { Education } from "./components/education";
import { Header } from "./components/header";
// import { Projects } from "./components/projects";
import { ProjectExperience } from "./components/project-experience";
import { Skills } from "./components/skills";
import { Summary } from "./components/summary";
import { WorkExperience } from "./components/work-experience";

// Metadata is now handled in a separate file since this is a client component

/**
 * Transform social links for command menu
 */
function getCommandMenuLinks(resumeData: ReturnType<typeof getResumeData>) {
  const links = [];

  if (resumeData.personalWebsiteUrl) {
    links.push({
      url: resumeData.personalWebsiteUrl,
      title: "Personal Website",
    });
  }

  return [
    ...links,
    ...resumeData.contact.social.map((socialMediaLink) => ({
      url: socialMediaLink.url,
      title: socialMediaLink.name,
    })),
  ];
}

export default function ResumePage() {
  const { language } = useLanguage();
  const [mounted, setMounted] = useState(false);
  const RESUME_DATA = getResumeData(language);
  const structuredData = generateResumeStructuredData();

  // Prevent hydration mismatch by waiting for mount
  useEffect(() => {
    setMounted(true);
  }, []);

  // Show nothing or minimal content during SSR/hydration to avoid mismatch
  if (!mounted) {
    return (
      <main className="container relative mx-auto min-h-screen p-4 md:p-16">
        <div className="mx-auto max-w-2xl">
          {/* Minimal placeholder to prevent layout shift */}
          <div className="h-screen" />
        </div>
      </main>
    );
  }

  return (
    <>
      <script
        type="application/ld+json"
        // biome-ignore lint/security/noDangerouslySetInnerHtml: Safe for JSON-LD structured data
        dangerouslySetInnerHTML={{
          __html: JSON.stringify(structuredData),
        }}
      />
      <main
        className="container relative mx-auto scroll-my-12 overflow-auto p-4 print:p-11 md:p-16"
        id="main-content"
      >
        <div className="sr-only">
          <h1>{RESUME_DATA.name}&apos;s Resume</h1>
        </div>

        <section
          className="mx-auto w-full max-w-2xl space-y-8 bg-white print:space-y-4 dark:bg-background"
          aria-label="Resume Content"
          data-language={language}
        >
          <div className="animate-fade-in" style={{ animationDelay: "0ms" }}>
            <Header />
          </div>

          <div className="space-y-8 print:space-y-4">
            <div className="animate-fade-in" style={{ animationDelay: "75ms" }}>
              <Summary summary={RESUME_DATA.summary} />
            </div>
            <div
              className="animate-fade-in"
              style={{ animationDelay: "150ms" }}
            >
              <WorkExperience work={RESUME_DATA.work} />
            </div>
            <div
              className="animate-fade-in"
              style={{ animationDelay: "190ms" }}
            >
              <ProjectExperience projects={RESUME_DATA.projectExperience} />
            </div>
            <div
              className="animate-fade-in"
              style={{ animationDelay: "225ms" }}
            >
              <Education education={RESUME_DATA.education} />
            </div>
            <div
              className="animate-fade-in"
              style={{ animationDelay: "300ms" }}
            >
              <Skills skills={RESUME_DATA.skills} />
            </div>
            {/* Side projects section - hidden for now
            <div
              className="animate-fade-in"
              style={{ animationDelay: "375ms" }}
            >
              <Projects projects={RESUME_DATA.projects} />
            </div>
            */}
          </div>
        </section>

        <nav className="print:hidden" aria-label="Quick navigation">
          <CommandMenu links={getCommandMenuLinks(RESUME_DATA)} />
        </nav>
      </main>
    </>
  );
}
