import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Section } from "@/components/ui/section";
import type { RESUME_DATA } from "@/data/resume-data";
import { cn } from "@/lib/utils";

type ProjectExperience = NonNullable<
  (typeof RESUME_DATA)["projectExperience"]
>[number];
type ProjectBadges = readonly string[];

interface BadgeListProps {
  className?: string;
  badges: ProjectBadges;
}

/**
 * Renders a list of badges for project experience
 * Handles both mobile and desktop layouts through className prop
 */
function BadgeList({ className, badges }: BadgeListProps) {
  if (badges.length === 0) return null;

  return (
    <ul
      className={cn("inline-flex list-none gap-x-1 p-0", className)}
      aria-label="Technologies used"
    >
      {badges.map((badge) => (
        <li key={badge}>
          <Badge
            variant="secondary"
            className="align-middle text-xs print:px-1 print:py-0.5 print:text-[8px] print:leading-tight"
          >
            {badge}
          </Badge>
        </li>
      ))}
    </ul>
  );
}

interface ProjectPeriodProps {
  start: ProjectExperience["start"];
  end?: ProjectExperience["end"];
}

/**
 * Displays the project period in a consistent format
 */
function ProjectPeriod({ start, end }: ProjectPeriodProps) {
  return (
    <div
      className="text-sm tabular-nums text-gray-500"
      title={`Project period: ${start} to ${end ?? "Present"}`}
    >
      {start} - {end ?? "Present"}
    </div>
  );
}

interface ProjectLinkProps {
  company: ProjectExperience["company"];
  link: ProjectExperience["link"];
}

/**
 * Renders project organization name with optional link
 */
function ProjectLink({ company, link }: ProjectLinkProps) {
  if (!link) {
    return <span>{company}</span>;
  }

  return (
    <a
      className="hover:underline"
      href={link}
      target="_blank"
      rel="noopener noreferrer"
      aria-label={`${company} project link`}
    >
      {company}
    </a>
  );
}

interface ProjectExperienceItemProps {
  project: ProjectExperience;
}

/**
 * Individual project experience card component
 * Handles responsive layout for badges (mobile/desktop)
 */
function ProjectExperienceItem({ project }: ProjectExperienceItemProps) {
  const { company, link, badges, title, start, end, description, highlights } =
    project;

  return (
    <Card className="border-none py-1 print:py-0">
      <CardHeader className="print:space-y-1">
        <div className="flex items-center justify-between gap-x-2 text-base">
          <h3 className="inline-flex items-center justify-center gap-x-1 font-semibold leading-none print:text-sm">
            <ProjectLink company={company} link={link} />
            <BadgeList
              className="hidden gap-x-1 sm:inline-flex"
              badges={badges}
            />
          </h3>
          <ProjectPeriod start={start} end={end} />
        </div>

        <h4 className="font-mono text-sm font-semibold leading-none print:text-[12px]">
          {title}
        </h4>
      </CardHeader>

      <CardContent>
        <div className="mt-2 text-xs leading-relaxed text-foreground/80 print:mt-1 print:text-[10px] print:leading-relaxed text-pretty">
          {description}
          {highlights && highlights.length > 0 && (
            <ul className="list-inside list-disc mt-1 space-y-0.5">
              {highlights.map((highlight) => (
                <li key={highlight} className="leading-relaxed print:leading-relaxed">{highlight}</li>
              ))}
            </ul>
          )}
        </div>
        <div className="mt-2">
          <BadgeList
            className="-mx-2 flex-wrap gap-1 sm:hidden"
            badges={badges}
          />
        </div>
      </CardContent>
    </Card>
  );
}

interface ProjectExperienceProps {
  projects: (typeof RESUME_DATA)["projectExperience"];
}

/**
 * Main project experience section component
 * Renders a list of project experiences in chronological order
 */
export function ProjectExperience({ projects }: ProjectExperienceProps) {
  if (!projects || projects.length === 0) return null;

  return (
    <Section>
      <h2 className="text-xl font-bold" id="project-experience">
        Project Experience
      </h2>
      <div
        className="space-y-4 print:space-y-0"
        role="feed"
        aria-labelledby="project-experience"
      >
        {projects.map((item) => (
          <article key={`${item.company}-${item.start}`}>
            <ProjectExperienceItem project={item} />
          </article>
        ))}
      </div>
    </Section>
  );
}
